import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 2D benchmark function combining a skewed quadratic bowl,
    sinusoidal modulation, and pairwise interactions to approximate target ELA features.

    Formula:
    f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x) + skew_term(x)

    Components:
    - quadratic_bowl: Creates a basic quadratic bowl shape.
    - sinusoidal_modulation: Adds oscillations to the landscape.
    - interaction_term: Introduces pairwise interactions between dimensions.
    - skew_term: Introduces skewness into the fitness distribution.
    """
    x1, x2 = x

    def quadratic_bowl(x):
        return x[0]**2 + x[1]**2

    def sinusoidal_modulation(x):
        return np.sin(x[0] * 2) + np.cos(x[1] * 3)

    def interaction_term(x):
        return x[0] * x[1] * 0.5

    def skew_term(x):
        return (x[0] + x[1])**3 * ( x[0] >= -1 and x[1] >= -1) * 0.001 #Only induce skewness in upper section to avoid domain collision

    return quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x) + skew_term(x)
